/**
 * Rewrite the `<auto-generated-urls>` block inside
 * `shared/test_config.py` with one `NAME: str = ""` class attribute per
 * `.env` URL key. The runtime values are hydrated by
 * `AppConfiguration.load_test_config`, which `setattr`s the matching
 * key onto `TestConfig`. When the file is missing entirely (legacy
 * projects scaffolded before task #207) the canonical template is
 * materialized so generated tests can still
 * `from shared.test_config import TestConfig`.
 */
import fs from "node:fs/promises";
import { safeJoin } from "@/features/projects/infrastructure/paths";
import type { Project } from "@/features/projects/domain/types";
import { applyTokens } from "@/features/codegen/infrastructure/templates";
import { PYTHON_TEST_CONFIG_CONTENT } from "@/features/architectures/infrastructure/architectureService";

/** Relative path to the scaffold-emitted Python TestConfig file. */
const PYTHON_TEST_CONFIG_REL = "shared/test_config.py";

const PY_URL_BLOCK_OPEN = "# <auto-generated-urls>";
const PY_URL_BLOCK_CLOSE = "# </auto-generated-urls>";

export async function regenerateTestConfig(
  project: Project,
  urlNames: string[],
): Promise<string | null> {
  const abs = safeJoin(project.rootPath, PYTHON_TEST_CONFIG_REL);
  const sorted = [...new Set(urlNames)].sort();
  const innerLines = sorted.map((n) => `    ${n}: str = ""`);

  let original: string | null = null;
  try {
    original = await fs.readFile(abs, "utf8");
  } catch {
    // file missing — fall through to template materialization
  }

  if (
    original === null ||
    !original.includes(PY_URL_BLOCK_OPEN) ||
    !original.includes(PY_URL_BLOCK_CLOSE)
  ) {
    const sharedDir = safeJoin(project.rootPath, "shared");
    try {
      await fs.mkdir(sharedDir, { recursive: true });
    } catch {
      return null;
    }
    const rendered = applyTokens(PYTHON_TEST_CONFIG_CONTENT, {
      namespace: project.namespace,
      solution: project.solutionName,
    });
    const seeded = replaceUrlMarkerBlock(
      rendered,
      PY_URL_BLOCK_OPEN,
      PY_URL_BLOCK_CLOSE,
      innerLines,
    );
    await fs.writeFile(abs, seeded);
    return PYTHON_TEST_CONFIG_REL;
  }

  const next = replaceUrlMarkerBlock(
    original,
    PY_URL_BLOCK_OPEN,
    PY_URL_BLOCK_CLOSE,
    innerLines,
  );
  if (next === original) return PYTHON_TEST_CONFIG_REL;
  await fs.writeFile(abs, next);
  return PYTHON_TEST_CONFIG_REL;
}

/**
 * Replace the lines between the (last) `openMarker` line and the next
 * `closeMarker` line with `innerLines`. When either marker is missing
 * the original text is returned unchanged.
 */
function replaceUrlMarkerBlock(
  original: string,
  openMarker: string,
  closeMarker: string,
  innerLines: string[],
): string {
  const lines = original.split(/\r?\n/);
  let openIdx = -1;
  let closeIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i]!.includes(openMarker)) {
      openIdx = i;
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j]!.includes(closeMarker)) {
          closeIdx = j;
          break;
        }
      }
      break;
    }
  }
  if (openIdx === -1 || closeIdx === -1) return original;
  const next = [
    ...lines.slice(0, openIdx + 1),
    ...innerLines,
    ...lines.slice(closeIdx),
  ];
  return next.join("\n");
}
